const grpc = require('@grpc/grpc-js');
const { db } = require('../db');
const { verifyGrpcMetadataAuth } = require('../auth');

async function getBillingStatement(call, callback) {
  const caller = await verifyGrpcMetadataAuth(call.metadata);
  if (!caller) {
    return callback({ code: grpc.status.UNAUTHENTICATED, message: 'Unauthenticated' });
  }

  const statementId = call.request.statementId;
  const statement = await db.query(
    'SELECT * FROM billing_statements WHERE id = $1 AND organization_id = $2',
    [statementId, caller.organizationId]
  );

  if (statement.rowCount === 0) {
    return callback({ code: grpc.status.NOT_FOUND, message: 'Statement not found or unauthorized' });
  }

  return callback(null, {
    statementId: statement.rows[0].id,
    amountDueCents: statement.rows[0].amount_cents,
    invoicePdfUrl: statement.rows[0].pdf_url
  });
}
